def f(x,places=3):return f'{float(x):,.{places}f}'
def main():
 counties=readcsv(D.parent/'county-baselines.csv');states=readcsv(D/'state-baselines.csv');scenarios=readcsv(D/'state-scenarios.csv');targets=readcsv(D/'county-scenarios.csv.gz');native=readcsv(D/'native-state-scenarios.csv');priority=json.loads((D/'priority-contract.json').read_text());official=readcsv(D/'official-county-candidates.csv');by={(r['year'],r['contest'],r['county_fips']):r for r in counties};base=next(r for r in states if r['year']=='2024' and r['contest']=='senate');P=int(base['pair_votes']);V=int(base['all_candidate_votes']);A=int(base['A_votes']);B=int(base['B_votes']);shift=float(base['tie_unbounded_shift_share_pp']);prefix='pref-2024-senate_mix-2024-senate_volume-base_';tt={(r['county_fips'],r['target']):r for r in targets if r['scenario_id'].startswith(prefix)}
 lines=['# Florida historical partisanship and conditional winning paths','', 'Research snapshot: **2026-10-18 UTC**. Complete coverage is67 counties and23,532 contest-specific historical native contexts. These are conditional arithmetic scenarios; historical turnout anchors are **not2026 projections**.','',f'The official2024 Senate baseline has Debbie Mucarsel-Powell (DEM) **{A:,}**, Rick Scott (REP) **{B:,}**, and176,645 valid votes for four other candidates. The pair deficit is **{B-A:,} votes**. At fixed historical county pair weights, a uniform **+{shift:.6f} percentage points of A share** ties; **+{shift+.5:.6f} share points** produces an illustrative **A+1 pair margin**. That cushion is{.01*P:,.2f} net votes, distinct from the{.01*V:,.2f} votes for A+1 on the all-candidate denominator. See the [official2024 Senate county table](https://results.elections.myflorida.com/DetailRpt.Asp?DATAMODE=&DIST=&ELECTIONDATE=11/5/2024&GRP=&PARTY=&RACE=USS) and [Clerk2024 statistics](https://clerk.house.gov/member_info/electionInfo/2024/statistics2024.pdf), Florida printedpage14.','', '## Election identity and current candidate scope','', 'November3,2026 is the **ClassIII special election** for the remainder of the term endingJanuary3,2029. The2022 Rubio–Demings Senate election is the same-seat midterm comparator. The2024 Scott–Mucarsel-Powell race is the other, ClassI seat and the required recent-volume priority basis. The2024 president and2020 president remain separate electorates; Florida had no2020 Senate election. Sources: [2026 dates](https://dos.fl.gov/elections/for-voters/election-dates/), [ClassIII roster](https://www.senate.gov/senators/Class_III.htm), [ClassI roster](https://www.senate.gov/senators/Class_I.htm), [2022 official returns](https://results.elections.myflorida.com/DetailRpt.Asp?DATAMODE=&DIST=&ELECTIONDATE=11/8/2022&GRP=&PARTY=&RACE=USS).','', 'The final official [Broward November3 list](https://browardvotes.gov/sites/default/files/list-of-candidates-for-november-elections.pdf), page1, names **Ashley Moody—Republican Party; Angie Nixon—Democratic Party; Neil J. Gillespie—No Party Affiliation**, with no Senate write-in entry. Its original bytes, text and inspected page image are retained; the state [current candidate database](https://dos.elections.myflorida.com/candidates/CanList.asp?OfficeCode=USS&elecid=20261103-GEN) is preserved separately, including defeated primary candidates. [Current mapping](data/baselines/source/current-ballot-mapping.json) uses the final county publication, not primary nominees, newsroom keys or historical DOE IDs. Actual November result-candidate IDs remain unverified. Historical A/B names below describe their own elections, not an estimate of Nixon/Moody performance. Gillespie is not counted as Democratic.','', 'The legal special/general outcome is the highest vote total; an equal highest total is resolved by lot under [100.181](https://www.flsenate.gov/Laws/Statutes/2026/100.181). There is no Senate RCV elimination or general runoff stage in this calculation. A+1 is a chosen pair cushion, not a statutory threshold. Every named other candidate must also be beaten. No lower-preference transfer, candidate effect or remaining-vote preference is inferred.','', '## Primary evidence and reconciliations','', 'The [DOS precinct index](https://dos.fl.gov/elections/data-statistics/elections-data/precinct-level-election-results/), updatedJune2,2026, describes statewide compilations of county-supervisor submissions and directs data questions to the submitting supervisor. All three original ZIPs are reused read-only with pinned hashes: [2024](https://dos.fl.gov/media/708761/2024-gen-outputofficial1.zip), [2022](https://dos.fl.gov/media/706300/2022-gen-outputofficial.zip), [2020](https://fldoswebumbracoprod.blob.core.windows.net/media/703763/2020-general-election-rev.zip). Own direct2024/2022 downloads now return200 and are byte-identical to the retained institutional-storage originals; earlier403 requests remain valid, separately retained observations. All208 members/1,707,538 rows and all19 original fields—including unrelated offices and overlapping recount files—remain intact. The selected extraction does not add recount files to base returns. [Member inventory](data/baselines/source/zip-member-inventory.json) and [receipts/reuse metadata](data/baselines/source/external-source-references.json) permit exact reconstruction.','', 'Own literal-slash canonical DOS requests recovered original200 county HTML for all four contexts. The2024 presidential body exactly matches the independently archived official county table. [Official candidate cells](data/baselines/official-county-candidates.csv) retain every candidate, county, sourceTR/TD and raw hash; all67 county sums equal every primary webtable control. Both Senate vectors independently match [Clerk2022](https://clerk.house.gov/member_info/electionInfo/2022/statistics2022.pdf), printedpages10–11, and Clerk2024. The original [NARA2024 four-page certificate](https://www.archives.gov/files/electoral-college/2024/ascertainment-florida.pdf) was independently text-extracted and visually inspected: page2 confirms Trump6,110,125; page4 confirms Ayyadurai/Ellis199 and Fox/McVay6. No county allocation is taken from that statewide certificate.','', 'The compiled native and official county universes **disagree**. In2024 Hardee, the ZIP has Scott6,017 vs official6,016 and Trump6,337 vs6,336. In2022 Seminole, Rubio is97,760 vs97,761. In2020 Monroe, compiled Trump/Biden/Jorgensen are10/5/1 below official; Seminole Trump/Biden are5/4 below. These eight named candidate/county discrepancies remain unadjusted in [all-cell reconciliation](data/baselines/source-discrepancies.csv), against the [2024 president](https://results.elections.myflorida.com/DetailRpt.Asp?DATAMODE=&DIST=&ELECTIONDATE=11/5/2024&GRP=&PARTY=&RACE=PRE) and [2020 president](https://results.elections.myflorida.com/DetailRpt.Asp?DATAMODE=&DIST=&ELECTIONDATE=11/3/2020&GRP=&PARTY=&RACE=PRE) originals as well as the Senate sources. The cause/revision chronology is unresolved.','', 'Generic `WriteinVotes` marks are41,918/9,896/3,347/24,468 for2024 president/2024 Senate/2022 Senate/2020 president. Legally counted named write-ins are205/13/267/1,055 respectively. These are different universes. Neither generic marks nor over/undervotes enter valid-vote county weights. No generic write-in marks are allocated to named candidates or rescaled to controls. A named write-in county allocation exists in the DOS tables; its precinct/method allocation remains unavailable.','', '## Complete historical candidate controls','', '“All” means valid votes for every published named candidate, including valid write-ins; “pair” means the named DEM+REP candidates. Counts are not ballots cast. Signed margins are A−B.','', '| Context | A | B | Other valid | All | Pair | A pair share % | Pair margin pp | Tie share shift pp | A counties |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
 for r in states:lines.append(f"| {r['year']} {r['contest']} | {int(r['A_votes']):,} | {int(r['B_votes']):,} | {int(r['other_valid_votes']):,} | {int(r['all_candidate_votes']):,} | {int(r['pair_votes']):,} | {100*float(r['A_pair_share']):.4f} | {float(r['pair_margin_pp']):+.4f} | {float(r['tie_unbounded_shift_share_pp']):+.6f} | {r['A_won_counties']} |")
 lines+=['','Complete state vectors, retaining source party labels and names:','']
 for year,contest in [('2024','senate'),('2022','senate'),('2024','president'),('2020','president')]:
  rs=[r for r in official if r['year']==year and r['contest']==contest];names=list(dict.fromkeys((r['candidate_name'],r['party']) for r in rs));parts=[f"{name} ({party}) {sum(int(r['votes']) for r in rs if r['candidate_name']==name and r['party']==party):,}" for name,party in names];lines+=['- **'+year+' '+contest+':** '+'; '.join(parts)+'.']
 lines+=['','NPA means no party affiliation; LPF is Libertarian Party of Florida. Each is preserved independently. The2022 Clerk expands “Val Demings” to “Val Butler Demings”; raw source labels are retained. The complete county vectors and exact source positions are in the linked candidate CSV; no missing rows are filled with invented zeroes.','', '## Every county and its conditional contribution','', 'The following2024 Senate targets use all67 counties, original pair weights and unshifted historical turnout. The2022 same-seat Senate and2024 presidential margins are separate comparisons. A positive A-share movement transfers votes from B at fixed pair volume: **+1share point = +2margin points =0.02×county pair votes in net gain**. The historical label uses the pair winner and closeness bands≤5,>5–10,>10margin points in the [268-row county baseline](data/county-baselines.csv). All candidate counts and separate all-vote shares/weights are retained there.','', '| County | 2024 Senate A−B margin pp | 2022 same-seat margin pp | 2024 president margin pp | Senate A share % | Pair weight % | Historical A−B net | Net gain per+1share pp | Tie target A share % | A+1 pair target share % |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
 for rnk in priority['all67_order']:
  fp=rnk['county_fips'];r=by[('2024','senate',fp)];r22=by[('2022','senate',fp)];rp=by[('2024','president',fp)];t=tt[(fp,'tie')];plus=tt[(fp,'Aplus1_pair_margin')]
  lines.append(f"| {r['county']} | {float(r['pair_margin_pp']):+.3f} | {float(r22['pair_margin_pp']):+.3f} | {float(rp['pair_margin_pp']):+.3f} | {100*float(r['A_pair_share']):.3f} | {100*float(r['state_pair_weight']):.3f} | {int(r['A_minus_B_votes']):+,} | {float(r['gain_net_votes_per_1pp_A_share']):,.2f} | {100*float(t['target_A_pair_share']):.3f} | {100*float(plus['target_A_pair_share']):.3f} |")
 lines+=['','These are one uniform statewide path, not requirements that each county win or reach one necessary share. A net gain anywhere offsets an equal loss elsewhere. With all66 other counties fixed at their original2024 Senate preferences/volumes, **every single-county-only tie is impossible**: even Miami-Dade would need109.582820% A pair share (its maximum gain by transferring every B vote is1,170,890, below the1,374,629 statewide deficit). The raw requirement, clipped display and infeasible status are separate in every scenario row. The adjustable selected-county CLI can change the other66 assumptions explicitly.','', '## Historical volume, mix and preference sensitivity','', 'The implementation separates three choices: statewide **all-valid contest volume**, county all-valid **mix**, and named-candidate preference/pair-participation anchor. Low7,758,014 uses observed2022 Senate volume; base10,757,428 uses2024 Senate; high11,067,456 uses2020 president. They are historical stress anchors, not a2026 turnout interval. Mix/preference anchors independently include2024 Senate,2022 same-seat Senate,2024 president and2020 president. County pair participation always uses that county’s chosen preference-anchor `(A+B)/all-valid`; it is never silently replaced by a statewide constant.','', 'For county c, `F_c=F*(mix county all-valid/mix state all-valid)`; `T_c=F_c*preference-anchor pair participation`; `s_c=anchor A/(A+B)`. Hold nonpair participation outside the pair. The [settings](data/baselines/scenario-settings.json), [144 statewide scenarios](data/baselines/state-scenarios.csv) and [9,648 county rows](data/baselines/county-scenarios.csv.gz) preserve every volume/mix/preference choice, pair/all denominators, weights, gains, clipped targets and selected-only thresholds. Every state calculation includes all67 counties, including the45 below priority.','', 'With2024 Senate preferences/participation fixed and base all-valid volume, mix alone changes the conditional deficit:','', '| County mix anchor | Pair volume | Baseline A−B net | Tie share shift pp | A+1 pair share shift pp |','|---|---:|---:|---:|---:|']
 for mix in ['2024-senate','2022-senate','2024-president','2020-president']:
  r=next(r for r in scenarios if r['preference_anchor']=='2024-senate' and r['mix_anchor']==mix and r['historical_volume_label']=='base' and r['target']=='tie');rp=next(z for z in scenarios if z['scenario_id']==r['scenario_id'].removesuffix('tie')+'Aplus1_pair_margin');lines.append(f"| {mix} | {f(r['pair_volume'],2)} | {float(r['baseline_A_minus_B']):+,.2f} | {f(r['bounded_shift_share_pp'],6)} | {f(rp['bounded_shift_share_pp'],6)} |")
 lines+=['','With2024 Senate mix/preferences fixed, the low/base/high all-valid volumes imply pair pools7,630,621.62 /10,580,783.00 /10,885,720.11. Scaling all counties together changes net-vote magnitudes, not the required6.495876share-point tie shift. Switching to2022 preferences is a distinct anchor, not an estimated candidate effect; its original same-seat tie shift is8.293797share points.','', 'For fixed pair weights, `M=ΣT_c(2s_c−1)` and the unbounded tie shift is `−M/(2ΣT_c)=(B−A)/(2(A+B))`. A+1 pair margin adds0.5share points only before clipping. The bounded solver finds `ΣT_c[2clip(s_c+δ,0,1)−1]=target_net`. It retains unbounded and feasible shifts separately. A+1 all-candidate margin targets0.01×F, not0.01×pair. Historical expected fractional votes are arithmetic outputs, not extra observed votes or a legal guarantee. In every county scenario, both solved pair candidates exceed the entire aggregate other-vote upper bound, so no individual held-fixed other candidate can defeat them in that scenario.','', '## Native geography, methods and priority contract','', 'County FIPS identities are independently verified from the [Census2024 Florida Gazetteer](https://www2.census.gov/geo/docs/maps-data/data/gazetteer/2024_Gazetteer/2024_gaz_counties_12.txt); this is a county identifier reference, not precinct geography approval. The [native-unit export](data/baselines/native-units.csv.gz) retains5,7102024 Senate,5,7122024 president,6,0132022 Senate and6,0972020 president contexts, all67 counties in each. Key components are raw county code/election number/precinct ID/polling label, separately scoped to contest/year. Source blanks/leading zeros remain. The [19-column definitions](https://dos.fl.gov/media/709209/final-precinct-level-elections-data-definitions-and-field-codes_20250624.pdf) provide **no voting-method column**. There is no candidate-by-method allocation. Precincts, split styles, central groups and polling sites are not equated; all native identities remain historical, unapproved for November2026 geometry.','', 'Concrete identities matter: Washington2022 has nine blank precinct IDs and three `1` IDs distinguished by polling labels; Leon9000 is a central early-vote label; Osceola presidential999/MAIN OFFICE EV is zero-valued and absent in Senate; Pinellas has286 MailBallot labels whose name does not prove a mail-only electorate. These raw contexts are retained, not matched across years by similar names. [Native coverage](data/baselines/native-coverage.json) and source rows preserve the exact verified scope.','', 'Native arithmetic has its own **compiled A+B** basis and every context stays in state sums. Three observed compiled statewide pair pools—7,676,368 /10,580,784 /10,965,752—scale each context’s own-year pair weights; there is no cross-year native join. All-valid native denominators and valid write-in allocation remain unknown. [141,192 native target rows](data/baselines/native-scenarios.csv.gz) and [24 state sums](data/baselines/native-state-scenarios.csv) retain native contributions/weights/gains, selected-only thresholds with every other native fixed, zero-pool contexts and clipping. In2024 Senate the compiled unbounded tie shift6.495879700share pp clips18 positive-pool contexts; the feasible shift is6.496265037. The A+1 bounded shift is6.996588485 with19 clipped contexts. These compiled-native sums are not silently reconciled to the one-vote-different certified county totals.','', f'The independently measured minimum80% is **22counties**,{priority["minimum80_total"]:,}/{V:,}={100*priority["minimum80_total"]/V:.6f}%;21counties total{priority["prior_total"]:,}, below the integer threshold{priority["threshold_integer_ceil"]:,}. Escambia contributes the crossing161,721. Top15={priority["top15_total"]:,} ({100*priority["top15_total"]/V:.6f}%). The remaining45counties contribute{priority["remainder_votes"]:,} and remain in every statewide calculation. The exact [full67 order](data/baselines/priority-order.csv) and [independent contract](data/baselines/priority-contract.json) use all six named valid candidates; no generic marks enter.','', '**Priority22 in order:** '+', '.join(r['county'] for r in priority['all67_order'][:22])+'.','', 'The [read-only peer witness](data/baselines/peer-agreement.json) checks2,479 primary county-candidate cells,211,874 raw source positions×19=4,025,606 equal fields,23,532 native contexts including registration/candidate/category/source positions,1,876 county controls,8,375 shared EAVS fields,2,412 bookclosing cells and all67 ordering/exact22 crossing. It pins the repaired peer contract `0c056e0ebfdb393d4fcb59676805122d8442f444200b9edaf7f4c979c5e9a173`,23,823,926bytes. Gulf’s singular poll-close and administrative clocks are null; split geography remains explicit. The coordinator subsequently granted historical dispatch acceptance at `data/coordinator-priority-acceptance.json`; that external path is the authority, with no reverse hash embedded here. It does not approve current precinct boundaries or operational source/candidate admission.','', '## Turnout, registration and counting rules','', 'The independently parsed [EAC2024 V2](https://www.eac.gov/sites/default/files/2026-02/2024_EAVS_for_Public_Release_nolabel_V2_csv.zip) and [EAC2022 V1.1](https://www.eac.gov/sites/default/files/2023-12/2022_EAVS_for_Public_Release_nolabel_V1.1_CSV.zip) cover all67 counties each. The [2024 instrument](https://www.eac.gov/sites/default/files/2024-04/2024_EAVS_FINAL_508c.pdf), pages1 and46–47, defines eligible/active/inactive registration, F1a participants whose ballots were counted, method categories and F2 source types. EAVS counted participation is10,999,125 in2024 and7,798,866 in2022; this is not valid Senate votes or necessarily all ballots issued/cast. Candidate votes cannot be allocated to methods from these county survey totals. Sentinels, blanks and comments remain; UOCAVA/provisional and method-source inconsistencies are not normalized into disjoint pools.','', 'DOS [2024 active bookclosing workbook](https://fldoswebumbracoprod.blob.core.windows.net/media/708493/1-party-by-county.xlsx) totals13,949,168, closingOctober7/generatedOctober17; [2022 workbook](https://fldoswebumbracoprod.blob.core.windows.net/media/706002/1-2022-gen_bycountybyparty.xlsx) totals14,503,978, closingOctober11/generatedOctober20 at9pm without a stated timezone. EAVS total eligible registration is15,740,083/15,574,971; EAVS active is14,028,831/14,497,121. These definitions/dates differ. Once-per-native compiled registration totals13,942,186/14,494,942, respectively6,982/9,036 below bookclosing. The compiled Senate all-marks+under/over totals11,002,524/7,796,912 differ from EAVS F1a by+3,399/−1,954. [Every county control](data/baselines/turnout-registration-controls.csv) preserves those differences; blanks are not imputed as undervotes, and repeated per-candidate registration is never summed repeatedly.','', 'Current2026 legal checks, observedOctober18: ordinary vote-by-mail receipt is7pm election day under [101.67](https://www.flsenate.gov/Laws/Statutes/2026/101.67); eligible overseas general-election ballots timely dated/postmarked may arrive within10days under [101.6952](https://www.flsenate.gov/Laws/Statutes/2026/101.6952). Mail signature cures under [101.68](https://www.flsenate.gov/Laws/Statutes/2026/101.68) and provisional evidence/cures under [101.048](https://www.flsenate.gov/Laws/Statutes/2026/101.048) have the applicable5pm second-day deadline—November5. The canvassing board determines countability; requested, returned, cured and accepted ballots are not interchangeable counts.','', 'Under current [102.141](https://www.flsenate.gov/Laws/Statutes/2026/102.141), tabulated early/mail results go to DOS within30minutes after polls close; subsequent precinct uploads are at least every45minutes, except provisional results, with notification of impediments. These are legal reporting requirements, **not measured website/API cadence**. Preserve preliminary/unofficial/recount/official/certified stages and cumulative corrections. The [2026 reporting timeline](https://dos.fl.gov/media/709430/election-results-reporting-timeline-ge-2026-v20250821.pdf) visibly says2026/updated20250821 despite a misleading PDF metadata/web title referring to2024: it lists first unofficialNovember7, recount-stageNovember12, county officialNovember16 and commissionNovember17. [102.112](https://www.flsenate.gov/Laws/Statutes/2026/102.112) and [102.111](https://www.flsenate.gov/Laws/Statutes/2026/102.111) govern the returns/certification clocks and potential corrected recertification. Ordinary commission meeting is9am, with8am on organizational-session days.','', 'Polls operate7am–7pm using the customary standard time at the county seat under [100.011](https://www.flsenate.gov/Laws/Statutes/2026/100.011). [49CFR71.5(f)](https://www.ecfr.gov/current/title-49/subtitle-A/part-71/section-71.5) defines the Florida Eastern/Central boundary through rivers/waterway and Gulf County. The [all67 authority inventory](data/baselines/county-authorities.csv) preserves nine Central counties,57 Eastern and split Gulf; geographic zones alone do not establish separate poll-closing schedules. The actual [Gulf Election Day page](https://votegulf.gov/voters/vote-on-election-day/) publishes simultaneous countywide7pm ET/6pm CT closure. The accepted historical contract keeps both operational-clock fields null, with operational evidence reviewed separately. Publisher timestamps may use another zone. Repeated source snapshots replace the same cumulative electorate rather than adding together; “precincts reporting” is not the fraction of votes counted.','', '## Offline live remainder calculator and reproduction','', 'The [offline calculator](data/baselines/live_remainder.py) fixes every counted candidate vote and forecasts **only an explicit remaining all-candidate contest pool**, its pair participation, pair preference and named-other allocation. Final denominator is counted all-candidate votes **plus remaining all-candidate contest votes**. A requested pair/all-candidate cushion uses that final denominator. Selected-pool thresholds fix counted votes and all other remaining pools at their supplied assumptions; plurality against each other candidate is checked separately. Unknown pool/preference/other allocation stays unknown; negative inputs are rejected; shares are explicitly clipped with input/used values retained. A zero remaining pair pool is not divided by zero.','', '[Fifteen saved synthetic inputs](data/baselines/synthetic-live-inputs.json) and [results](data/baselines/synthetic-live-results.json) cover unknowns, no pool, negative input, impossible/secured pair paths, clipping at both ends, no positive pair pool, tied/all-zero counts, an independent candidate defeating the pair leader, and a selected county with other66 fixed and the correct final all-vote cushion. They are arithmetic cases, not calibrated probabilities or genuine election-night observations.','', '```sh','export PYTHONDONTWRITEBYTECODE=1','python3 senate/2026/florida/data/baselines/reproduce.py','python3 senate/2026/florida/data/baselines/calculate.py --county Miami-Dade --others-share-shift-pp 0 --target-margin-pp 0','python3 senate/2026/florida/data/baselines/live_remainder.py --input senate/2026/florida/data/baselines/synthetic-live-inputs.json','```','', 'Reproduction is offline from retained originals; [acquisition script](data/baselines/acquire.py) and receipts preserve public retrieval paths. A fresh capture should use a new ID and retain old bodies, not overwrite evidence. [Schema](data/baselines/source/SCHEMA.md) defines every denominator/key/table and [validation](data/baselines/validation.json) verifies source hashes/CRCs, exact coverage/candidate balances, native/source identities, integer80 crossing, weights/bounded targets, live final denominators/edge cases, relative links and asset bounds. [Owned asset manifest](data/baselines/asset-manifest.json) measures every owned artifact and pinned original reference; every stored asset is strictly below40,000,000bytes. No dependency/cache directory is retained.','', 'Material limits remain: no certified native valid-write-in/method allocation, no explanation for the eight named source discrepancies, no current native boundary/ballot-style crosswalk, no verified November result-candidate IDs or demonstrated live publication cadence, and no sourced outstanding2026 pool or calibrated probability. These gaps do not remove any county/native context from historical arithmetic.']
 # Typographic spacing for prose is intentional; do not alter native keys or source values.
 text='\n'.join(lines)+'\n'
 parts=re.split(r'(```[\s\S]*?```|`[^`]*`|https?://[^\s)]+)',text)
 for i in range(0,len(parts),2):
  textpart=parts[i]
  words='is|and|not|official|the|The|all|All|no|No|for|with|in|In|observed|direct|earlier|original|Own|are|return|page|pages|November|January|June|October|generated|closing|updated|Trump|Scott|Rubio|Biden|Jorgensen|Ayyadurai/Ellis|Fox/McVay|following|Clerk|NARA|EAC'
  textpart=re.sub(r'\b('+words+r')(?=\d)',r'\1 ',textpart)
  textpart=re.sub(r'(?<=\d)(?=counties|county|share|margin|days|bytes|rows|fields|native|source)', ' ',textpart)
  textpart=re.sub(r',(?=20\d{2}\b)',', ',textpart)
  for before,after in [('January3','January 3'),('updatedJune2','updated June 2'),('October7','October 7'),('October11','October 11'),('October17','October 17'),('October20','October 20'),('other66','other 66'),('integer80','integer 80'),('below40','below 40'),('outstanding2026','outstanding 2026'),('endingJanuary','ending January'),('ClassIII','Class III'),('ClassI','Class I'),('endingJanuary','ending January'),('printedpages','printed pages '),('printedpage','printed page '),('sourceTR/TD','source TR/TD'),('Senate/2024','Senate / 2024'),('are205','are 205'),('is105','is 105'),('the107','the 107'),('per+1','per +1'),('=0.02','= 0.02'),('bands≤','bands ≤'),('>10margin','>10 margin'),('by+3','by +3')]:textpart=textpart.replace(before,after)
  parts[i]=textpart
 text=''.join(parts)
 (D.parent.parent/'county-partisanship.md').write_text(text)
if __name__=='__main__':main()
